<script setup lang="ts">
import {onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {actionLoopApi as api} from '@/api/actionLoop'
const loading=ref(true),actions=ref<any[]>([]),dashboard=ref<any>({}),selected=ref<any>(),form=ref({title:'',owner_id:'',event_id:'',evidence_content_ids:'',risk_level:'medium',budget_cents:0});const empty='暂无行动。行动必须从预警、推演或决策室创建，并绑定可访问的来源证据。'
async function load(){loading.value=true;try{[actions.value,dashboard.value]=await Promise.all([api.list(),api.dashboard()])}finally{loading.value=false}}async function create(){try{const x=await api.create({...form.value,evidence_content_ids:form.value.evidence_content_ids.split(',').map(x=>x.trim()).filter(Boolean),budget_cents:Number(form.value.budget_cents)});actions.value=[x,...actions.value];ElMessage.success('行动已创建')}catch(e:any){ElMessage.error(e?.response?.data?.detail||'创建失败')}}async function open(x:any){selected.value=await api.detail(x.id)}async function approve(){selected.value=await api.approve(selected.value.id);await load();await open(selected.value)}async function start(){await api.start(selected.value.id,crypto.randomUUID());await load();await open(selected.value)}onMounted(load)
</script>
<template><main class="page"><header><div><small>ACTION LOOP</small><h1>行动闭环与影响验证</h1><p>从证据支持的决策到执行、回执、影响测量和复盘。</p></div><span>实时租户数据</span></header><section class="metrics"><article><span>行动总数</span><strong>{{dashboard.total||0}}</strong></article><article><span>执行预算</span><strong>¥{{((dashboard.budget_cents||0)/100).toFixed(2)}}</strong></article><article><span>已消耗</span><strong>¥{{((dashboard.spent_cents||0)/100).toFixed(2)}}</strong></article><article><span>状态数</span><strong>{{Object.keys(dashboard.by_status||{}).length}}</strong></article></section><section class="layout"><div><div class="head"><h2>行动看板</h2><button @click="load">刷新</button></div><div v-if="loading" class="empty">正在加载...</div><div v-else-if="!actions.length" class="empty">{{empty}}</div><button v-for="x in actions" :key="x.id" class="row" @click="open(x)"><span><b>{{x.title}}</b><small>{{x.risk_level}} · {{x.status}}</small></span><time>{{x.due_at?new Date(x.due_at).toLocaleString():'未设置截止时间'}}</time></button></div><form class="composer" @submit.prevent="create"><h2>创建行动</h2><p>至少绑定事件、推演或决策室；无证据时拒绝创建。</p><input v-model="form.title" required placeholder="行动标题"><input v-model="form.owner_id" required placeholder="负责人用户 ID"><input v-model="form.event_id" placeholder="事件 ID"><input v-model="form.evidence_content_ids" placeholder="证据内容 ID，以逗号分隔"><select v-model="form.risk_level"><option>low</option><option>medium</option><option>high</option></select><input v-model="form.budget_cents" type="number" min="0" placeholder="预算（分）"><button>创建行动</button></form></section><section v-if="selected" class="detail"><div class="head"><div><small>{{selected.status}}</small><h2>{{selected.title}}</h2></div><div><button v-if="selected.status==='pending_approval'" @click="approve">批准</button><button v-if="selected.status==='approved'||selected.status==='draft'" @click="start">开始执行</button></div></div><p>{{selected.description||'未填写描述'}}</p><div class="evidence"><b>来源证据</b><code v-for="id in selected.evidence_content_ids" :key="id">{{id}}</code><span v-if="!selected.evidence_content_ids?.length">无证据</span></div><h3>执行步骤与回执</h3><div v-if="!selected.steps?.length" class="empty">尚未配置步骤。</div><table v-else><tr><th>序号</th><th>渠道</th><th>状态</th></tr><tr v-for="s in selected.steps" :key="s.id"><td>{{s.sequence}}</td><td>{{s.channel}}</td><td>{{s.status}}</td></tr></table><h3>影响指标</h3><div class="empty">暂无真实影响测量，不显示模拟结果。</div></section></main></template>
<style scoped>.page{max-width:1200px;margin:auto;padding:32px;color:#19251f}.page header,.head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px}.page h1{font-size:32px;margin:6px 0}.page h2{font-size:20px}.page p{color:#63716a}.page small{color:#197167;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);margin:24px 0;border:1px solid #d4dfda}.metrics article{padding:16px;background:#fff;border-right:1px solid #d4dfda}.metrics span,.metrics strong{display:block}.metrics strong{font-size:25px;margin-top:8px}.layout{display:grid;grid-template-columns:1.3fr .7fr;gap:28px}.row{width:100%;display:flex;justify-content:space-between;text-align:left;border:0;border-bottom:1px solid #d8e1dd;background:#fff;padding:15px 10px;cursor:pointer;color:inherit}.row b,.row small{display:block}.row small{color:#6a7871;margin-top:5px}.composer,.detail{margin-top:28px;padding:20px;background:#fff;border:1px solid #d4dfda}.composer{display:grid;gap:10px}.composer h2,.composer p{grid-column:1/-1}.composer input,.composer select{padding:10px;border:1px solid #bdcbc4;border-radius:4px}button{border:0;background:#197167;color:#fff;border-radius:4px;padding:10px 14px;cursor:pointer}.evidence{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:12px;background:#f4f7f5}.evidence code{background:#e2eeea;padding:4px 6px}.empty{text-align:center;padding:35px;color:#728078}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #d8e1dd}@media(max-width:760px){.page{padding:72px 14px 24px}.metrics{grid-template-columns:1fr 1fr}.layout{grid-template-columns:1fr}.page header{display:block}.row{display:block}.row time{display:block;margin-top:8px}}</style>
